/**
 * Vertex 结构的伪代码描述.
 * 以实际的 C++ 表示，路径通常为Vertex*型，
 * 而我们描述的许多代码段
 * 或者要求解引用操作符 *，或者使用
 * -> 操作符，而不用。操作符。
 * 显然，这不利于对基本算法思路的理解。
 */
struct Vertex
{
    List     adj;      // 邻接 list（表）
    bool     known;
    DistType  dist;   // DistType 很可能是int型量
    Vertex     path;   // 如上所述，很可能是Vertex*型
        // 其他数据和成员函数视需要而定
};

/**
